/* Fit small longitude corrections for the outer planets by least squares
 * against JPL DE440 heliocentric longitudes (tools/helio-sample.json,
 * generated by the proven Python stack from public-domain DE440 data).
 * Prints coefficients to paste into engine.js plus residual stats.
 * Run: node tools/fit-corrections.js
 */
"use strict";
const fs = require("fs");
let src = fs.readFileSync(__dirname + "/../js/engine.js", "utf8");
src = src.replace("const Engine =", "globalThis.__X = {ELEMENTS, elementsToRect, dayNumber, rev}; const Engine =");
fs.writeFileSync("/tmp/eng-fit.cjs", src);
require("/tmp/eng-fit.cjs");
const { ELEMENTS, elementsToRect, dayNumber, rev } = globalThis.__X;
const sample = require("./helio-sample.json");

function solve(A, b) { // Gaussian elimination for small systems
  const n = b.length;
  const M = A.map((row, i) => [...row, b[i]]);
  for (let c = 0; c < n; c++) {
    let piv = c;
    for (let r = c + 1; r < n; r++) if (Math.abs(M[r][c]) > Math.abs(M[piv][c])) piv = r;
    [M[c], M[piv]] = [M[piv], M[c]];
    for (let r = 0; r < n; r++) {
      if (r === c) continue;
      const f = M[r][c] / M[c][c];
      for (let k = c; k <= n; k++) M[r][k] -= f * M[c][k];
    }
  }
  return M.map((row, i) => row[n] / row[i]);
}
function fit(rows) { // rows: [basisVector, target]
  const n = rows[0][0].length;
  const A = Array.from({ length: n }, () => Array(n).fill(0));
  const b = Array(n).fill(0);
  for (const [x, y] of rows) for (let i = 0; i < n; i++) { b[i] += x[i] * y; for (let j = 0; j < n; j++) A[i][j] += x[i] * x[j]; }
  return solve(A, b);
}
const wrapDiff = (a, b) => ((a - b + 540) % 360) - 180;
const D2R = Math.PI / 180;

const sin = (x) => Math.sin(x * D2R), cos = (x) => Math.cos(x * D2R);

function bases(name, d, els) {
  const t = d / 36525; // centuries from J2000-ish (d is days from 2000 Jan 0)
  const Mown = ELEMENTS[name] ? ELEMENTS[name](d).M : 0;
  if (name === "Jupiter" || name === "Saturn") {
    const S = els.Jupiter.M - els.Saturn.M; // synodic argument, ~20 yr cycle
    return [1, t, t * t, sin(Mown), cos(Mown), sin(2 * Mown), cos(2 * Mown), sin(S), cos(S), sin(2 * S), cos(2 * S)];
  }
  if (name === "Pluto") {
    const P = 238.9508 + 0.00400703 * d;
    return [1, t, t * t, sin(P), cos(P)];
  }
  return [1, t, t * t, sin(Mown), cos(Mown), sin(2 * Mown), cos(2 * Mown)];
  return [1];
}

for (const name of ["Jupiter", "Saturn", "Uranus", "Neptune", "Pluto"]) {
  const rows = [];
  for (const s of sample) {
    const d = dayNumber(s.utc_ms);
    const els = {};
    for (const p of ["Jupiter", "Saturn"]) els[p] = ELEMENTS[p](d);
    let h;
    if (name === "Pluto") {
      // helio lon from the Schlyter Pluto series (same code path as engine plutoLon, minus the geo shift)
      const P = 238.9508 + 0.00400703 * d;
      const lon = P - 19.799 * Math.sin(P*Math.PI/180) + 19.848 * Math.cos(P*Math.PI/180) + 0.897 * Math.sin(2*P*Math.PI/180) - 4.956 * Math.cos(2*P*Math.PI/180) + 0.610 * Math.sin(3*P*Math.PI/180) + 1.211 * Math.cos(3*P*Math.PI/180) - 0.341 * Math.sin(4*P*Math.PI/180) - 0.190 * Math.cos(4*P*Math.PI/180) + 0.128 * Math.sin(5*P*Math.PI/180) - 0.034 * Math.cos(5*P*Math.PI/180) - 0.038 * Math.sin(6*P*Math.PI/180) + 0.031 * Math.cos(6*P*Math.PI/180);
      h = { lon: rev(lon) };
    } else {
      h = elementsToRect(ELEMENTS[name](d));
    }
    const err = wrapDiff(s[name], h.lon); // truth - JS, degrees
    rows.push([bases(name, d, els), err]);
  }
  const coef = fit(rows);
  let worst = 0, sum = 0;
  for (const [x, y] of rows) {
    const pred = x.reduce((a, xi, i) => a + xi * coef[i], 0);
    const res = Math.abs(y - pred) * 60;
    worst = Math.max(worst, res); sum += res;
  }
  console.log(name.padEnd(8),
    "coef(deg)=", coef.map((c) => c.toFixed(6)).join(", "),
    " worst residual " + worst.toFixed(2) + "'  mean " + (sum / rows.length).toFixed(2) + "'");
}
